elements.variants_sample:
HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("default"); Text("default").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("accent"); Text("accent").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("transparent"); Text("transparent").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { SplitView() { Text("Content"); Button("Action") }.variant("inline"); Text("inline").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { SplitView() { Text("Content"); Button("Action") }.variant("compactInline"); Text("compactInline").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { SplitView() { Text("Content"); Button("Action") }.variant("overlay"); Text("overlay").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { SplitView() { Text("Content"); Button("Action") }.variant("compactOverlay"); Text("compactOverlay").font(.caption).foregroundStyle(.secondary) }
}

elements.sample:
NavigationSplitView {
  List {
    Label("Inbox", systemImage: "tray")
    Label("Sent", systemImage: "paperplane")
    Label("Archive", systemImage: "archivebox")
  }.navigationTitle("Mail")
} detail: {
  Text("Select a message")
}

Sheet("New reminder", message: "It is added to your Today list.", actions: { Button("Cancel"); Button("Add") }) {
  TextField("Title", text: "Call the dentist")
  Toggle("Remind me on a day", isOn: true)
}

TabView {
  Tab("Home", systemImage: "house") { Text("Welcome home") }
  Tab("Search", systemImage: "magnifyingglass") { Text("Search the library") }
  Tab("Profile", systemImage: "person") { Text("Your profile") }
}
